/* @lc app=leetcode id=3165 lang=kotlin */
class Solution { fun maximumSumSubsequence(nums: IntArray, queries: Array<IntArray>): Int = nums.size.let { n -> Array(4 * n + 5) { LongArray(4) }.let { tree -> DeepRecursiveFunction<IntArray, Unit> { args -> args[0].let { node -> args[1].let { l -> args[2].let { r -> args[3].let { pos -> args[4].let { v -> if (l == r) tree[node].also { T -> T[0] = 0 }.also { T -> T[1] = 0 }.also { T -> T[2] = 0 }.also { T -> T[3] = maxOf(0L, v.toLong()) } else ((l + r) / 2).let { mid -> (if (pos <= mid) callRecursive(intArrayOf(2 * node, l, mid, pos, v)) else callRecursive(intArrayOf(2 * node + 1, mid + 1, r, pos, v))).run { tree[2 * node].let { L -> tree[2 * node + 1].let { R -> tree[node].also { T -> T[0] = maxOf(L[0] + R[2], L[1] + R[0]) }.also { T -> T[1] = maxOf(L[0] + R[3], L[1] + R[1]) }.also { T -> T[2] = maxOf(L[2] + R[2], L[3] + R[0]) }.also { T -> T[3] = maxOf(L[2] + R[3], L[3] + R[1]) } } } } } } } } } } }.let { update -> nums.indices.forEach { i -> update.callRecursive(intArrayOf(1, 0, n - 1, i, nums[i])) }.run { queries.fold(0L) { sum, q -> update.callRecursive(intArrayOf(1, 0, n - 1, q[0], q[1])).run { (sum + (tree[1].maxOrNull() ?: 0L)) % 1000000007 } }.toInt() } } } } }